allocation_probe.source:
package actionprobe

import (
	"testing"

	r "gopurs/output/gopurs_runtime"
	p "gopurs/output/purescript/p_root"
)

var sink r.Value

type actionCase struct {
	name string
	get  func() r.Value
	want int64
}

func cases() []actionCase {
	return []actionCase{
		{"Polymorphism", p.Get_Test_Polymorphism_act, 10000000},
		{"RowToList", p.Get_Test_RowToList_act, 5},
	}
}

func check(tb testing.TB, name string, got r.Value, want int64) {
	tb.Helper()
	if got.Type != r.TypeInt || got.IntVal != want {
		tb.Fatalf("%s: got tag=%d integer=%d; want tag=%d integer=%d", name, got.Type, got.IntVal, r.TypeInt, want)
	}
}

func TestActionAllocations(t *testing.T) {
	for _, c := range cases() {
		t.Run(c.name, func(t *testing.T) {
			// Resolve the getter outside the measured action, as the benchmark
			// harness does; invoke the real action only through runtime.Apply.
			action := c.get()
			for i := 0; i < 100; i++ {
				check(t, c.name, r.Apply(action, r.Value{}), c.want)
			}
			allocs := testing.AllocsPerRun(10000, func() {
				sink = r.Apply(action, r.Value{})
			})
			check(t, c.name, sink, c.want)
			t.Logf("ALLOCATION name=%s result=%d tag=%d runs=10000 allocs_per_op=%.6f", c.name, sink.IntVal, sink.Type, allocs)
		})
	}
}

// Optional diagnostic timing only. Official Go/C timings come from the
// unchanged benchmark campaign, not from this isolated allocation probe.
func BenchmarkRealActions(b *testing.B) {
	for _, c := range cases() {
		b.Run(c.name, func(b *testing.B) {
			action := c.get()
			check(b, c.name, r.Apply(action, r.Value{}), c.want)
			b.ReportAllocs()
			b.ResetTimer()
			for i := 0; i < b.N; i++ {
				sink = r.Apply(action, r.Value{})
			}
			b.StopTimer()
			check(b, c.name, sink, c.want)
		})
	}
}
